SELECT country, COUNT(customer_id) AS customer_count
FROM customers
GROUP BY country;

SELECT SUM(revenue_usd) AS total_revenue
FROM monthly_revenue
WHERE year = 2024 AND month = 1;

SELECT category, SUM(quantity) AS total_quantity
FROM orders
GROUP BY category;

SELECT AVG(customer_rating) AS avg_rating
FROM orders
WHERE customer_rating IS NOT NULL;

SELECT 
    COUNT(CASE WHEN discount_pct > 0.20 THEN 1 END) * 100.0 / COUNT(*) AS proportion_percent
FROM orders;

SELECT customer_id, total_spend_usd
FROM customers
WHERE total_spend_usd > (SELECT AVG(total_spend_usd) * 2 FROM customers);
